'use strict';
let comparisonData=null;routes.push(['model-results','Model evaluation']);$('#nav').innerHTML=routes.map(([r,n])=>`<a href="#${r}">${n}</a>`).join('');
const pct=x=>(x*100).toFixed(1)+'%';
renderers['model-results']=()=>heading('Model evaluation','Measured performance on the UCI dataset, not clinical validation.')+(comparisonData?`<div class="warning">The earlier holdout has already been inspected. Nested grouped cross-validation repeats model selection on each training fold; it provides a broader estimate, not external patient validation. No patient IDs are available.</div><div class="grid">${card('Selected model',`<div class="big">${comparisonData.selected}</div><p>Chosen by training cross-validation macro F1. No oversampling or duplicate leakage.</p>`)}${card('Nested evaluation',`<div class="big">${pct(comparisonData.nested.report.accuracy)}</div><p>Accuracy across all 452 out-of-fold predictions.</p><p>Macro F1 ${comparisonData.nested.report['macro avg']['f1-score'].toFixed(3)} · High-risk recall ${pct(comparisonData.nested.report['high risk'].recall)} · Mid-risk recall ${pct(comparisonData.nested.report['mid risk'].recall)}</p>`)}</div>${card('Original holdout comparison',`<div class="evaluation-table"><table><caption>Same 89 test records · settings selected on 363 training records</caption><thead><tr><th>Method</th><th>Training CV macro F1</th><th>Test accuracy</th><th>Test macro F1</th><th>High-risk recall</th><th>Mid-risk recall</th></tr></thead><tbody>${comparisonData.models.map(r=>`<tr><td>${esc(r.model)}${r.model===comparisonData.selected?' (selected)':''}</td><td>${r.cv_macro_f1.toFixed(3)}</td><td>${pct(r.report.accuracy)}</td><td>${r.report['macro avg']['f1-score'].toFixed(3)}</td><td>${pct(r.report['high risk'].recall)}</td><td>${pct(r.report['mid risk'].recall)}</td></tr>`).join('')}</tbody></table></div><p>Class support: 16 high-risk, 50 low-risk, 23 mid-risk examples. Small counts make scores uncertain.</p><p>35 measurement groups have contradictory labels. Removing duplicates does not resolve that label ambiguity.</p><a href="comparison.json" download>Download full evaluation</a>`)}<p class="muted">Source: Ahmed, UCI Maternal Health Risk · grouped evaluation · 11 October 2026. The model does not estimate actual complication outcomes.</p>`:empty('Loading evaluation…'));
fetch('comparison.json').then(r=>r.json()).then(d=>{comparisonData=d;if(location.hash==='#model-results')render()}).catch(()=>{});
